/** Public ordinary-file decoders consume the hosted-generated bytes, independently of any
 * transport adapter. Document grammar remains owned by the existing document fixture suites. */
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import {
  parseBlobWriteResult, classifyBlobWriteAnswer, decodeBlobOutcomeAnswer,
  decodeHostedCapabilities, HostedAnswerError, HostedOutcomeError,
  type BlobWriteExpected, type HostedAnswer,
} from "../src/hosted-transport/index.js";
import { blobVersion } from "../src/versioning.js";

const directory = path.join(path.dirname(fileURLToPath(import.meta.url)), "fixtures/hosted-sync-v1");
interface Exchange {
  name: string; route: string;
  request: { headers: Record<string, string>; body: string; bodyBase64?: string };
  response: { status: number; headers: Record<string, string>; body?: string; bodyBase64?: string };
}
const index = JSON.parse(readFileSync(path.join(directory, "index.json"), "utf8")) as {source: string; exchanges: {name: string; file: string}[]};
const exchanges = index.exchanges.filter(entry => entry.name.startsWith("blob-")).map(entry => JSON.parse(readFileSync(path.join(directory, entry.file), "utf8")) as Exchange);
const fixture = (name: string): Exchange => exchanges.find(exchange => exchange.name === name) ?? assert.fail(`Missing ${name}`);
const json = (exchange: Exchange): any => JSON.parse(exchange.response.body!);
const answer = (exchange: Exchange): HostedAnswer => ({status: exchange.response.status, headers: new Headers(exchange.response.headers), body: json(exchange)});
function expectedFor(exchange: Exchange): BlobWriteExpected {
  if (!exchange.request.bodyBase64) {
    const {bundleId: _bundle, ...expected} = JSON.parse(exchange.request.body);
    return expected;
  }
  const headers = exchange.request.headers;
  const operationId = exchange.route === "/sync/v1/blob-create" ? "blobs.create.v1" : "blobs.replace.v1";
  const key = Buffer.from(headers["x-superbee-blob-key"]!, "base64url").toString("utf8");
  return operationId === "blobs.create.v1"
    ? {operationId, key, expectedVersion: null, expectedContentType: null, version: headers["x-superbee-blob-version"]!, contentType: headers["x-superbee-content-type"]!}
    : {operationId, key, expectedVersion: headers["x-superbee-expected-version"]!, expectedContentType: headers["x-superbee-expected-content-type"]!, version: headers["x-superbee-blob-version"]!, contentType: headers["x-superbee-content-type"]!};
}
const identityFor = (exchange: Exchange) => ({requestId: exchange.request.headers["x-superbee-write-request"]!, binding: exchange.request.headers["x-superbee-checkout"]!});
const digest = (letter: string) => `sha256:${letter.repeat(64)}`;
const clone = <T>(value: T): T => structuredClone(value);

// The copied family remains one provenance-bound inventory; no hand-authored blob goldens.
test("hosted blob exchanges retain binary bytes and decode through the public result and outcome grammar", () => {
  assert.match(index.source, /^Holaxis-ai\/superbee-hosted [0-9a-f]{40}$/);
  assert.deepEqual(exchanges.map(exchange => `${exchange.name}.json`).sort(), readdirSync(directory).filter(name => name.startsWith("blob-")).sort());
  assert.ok(exchanges.length > 0);
  for (const exchange of exchanges) {
    if (["/sync/v1/blob-create", "/sync/v1/blob-replace", "/sync/v1/blob-delete"].includes(exchange.route)) {
      const parsed = classifyBlobWriteAnswer(answer(exchange), expectedFor(exchange));
      const body = json(exchange);
      assert.equal(parsed.row.answer, exchange.response.status === 200 ? body.ok ? "200 ok" : `200 ${body.error.code}` : exchange.response.status === 428 ? "428 deletions_held" : "400", exchange.name);
      if (exchange.response.status === 200) assert.deepEqual(parsed.result, body, exchange.name);
    }
    if (exchange.route === "/sync/v1/outcome" && exchange.response.status === 200) {
      const body = json(exchange);
      const result = decodeBlobOutcomeAnswer(body, {...expectedFor(exchange), ...identityFor(exchange)});
      assert.equal(result.status, body.status, exchange.name);
      if (result.status !== "absent") assert.deepEqual(result.result, body.result, exchange.name);
    }
    if (exchange.request.bodyBase64 !== undefined) {
      const bytes = new Uint8Array(Buffer.from(exchange.request.bodyBase64, "base64"));
      assert.equal(Buffer.from(bytes).toString("base64"), exchange.request.bodyBase64);
      assert.equal(String(bytes.length), exchange.request.headers["content-length"]);
      if (exchange.response.status === 200) assert.equal(blobVersion(bytes), exchange.request.headers["x-superbee-blob-version"]);
    }
  }
  const read = fixture("blob-read-200-binary");
  const bytes = new Uint8Array(Buffer.from(read.response.bodyBase64!, "base64"));
  const pin = JSON.parse(read.request.body);
  assert.equal(blobVersion(bytes), pin.version);
  assert.equal(read.response.headers["x-superbee-blob-version"], pin.version);
  assert.equal(read.response.headers["x-superbee-content-type"], pin.contentType);
  assert.equal(read.response.headers["content-length"], String(bytes.length));
});

test("blob success validates operation, safe Unicode key, exact digest and MIME, including no-op and removed-head semantics", () => {
  for (const name of ["blob-create-200-ok", "blob-replace-200-noop", "blob-replace-200-type-only", "blob-delete-200-ok"]) {
    const exchange = fixture(name), expected = expectedFor(exchange), good = json(exchange);
    assert.deepEqual(parseBlobWriteResult(good, expected), good);
    const variants = [
      {...good, operationId: "documents.delete.v1"},
      {...good, data: {...good.data, key: "other.svg"}},
      {...good, data: {...good.data, version: digest("a")}},
      {...good, data: {...good.data, contentType: "application/pdf"}},
      {...good, data: {...good.data, contentType: ` ${good.data.contentType}`}},
      {...good, data: {...good.data, documentId: good.data.key}},
      {...good, error: {code: "version_conflict"}},
    ];
    for (const value of variants) assert.throws(() => parseBlobWriteResult(value, expected), HostedAnswerError, name);
    for (const key of ["../outside.bin", "hidden/.file", "document.md/image.bin", `folder/${"é".repeat(256)}.bin`, "bad\ud800.bin"])
      assert.throws(() => parseBlobWriteResult({...good, data: {...good.data, key}}, {...expected, key}), HostedAnswerError);
    if (expected.operationId === "blobs.delete.v1") {
      assert.throws(() => parseBlobWriteResult({...good, data: {...good.data, deleted: false}}, expected), HostedAnswerError);
      assert.throws(() => parseBlobWriteResult(good, {...expected, expectedVersion: digest("a")}), HostedAnswerError);
      assert.throws(() => parseBlobWriteResult(good, {...expected, expectedContentType: "application/pdf"}), HostedAnswerError);
    }
  }
  const create = fixture("blob-create-200-ok");
  assert.throws(() => parseBlobWriteResult({...json(create), data: {...json(create).data, changed: false}}, expectedFor(create)), HostedAnswerError);
  const noop = fixture("blob-replace-200-noop");
  assert.throws(() => parseBlobWriteResult({...json(noop), data: {...json(noop).data, changed: true}}, expectedFor(noop)), HostedAnswerError);
  const typeOnly = fixture("blob-replace-200-type-only");
  assert.throws(() => parseBlobWriteResult({...json(typeOnly), data: {...json(typeOnly).data, changed: false}}, expectedFor(typeOnly)), HostedAnswerError);
  const valid = expectedFor(create);
  const boundaryKey = `${"é".repeat(254)}.bin`;
  assert.equal(parseBlobWriteResult({...json(create), data: {...json(create).data, key: boundaryKey}}, {...valid, key: boundaryKey}).ok, true);
  assert.throws(() => parseBlobWriteResult({...json(create), data: {...json(create).data, key: `${boundaryKey}x`}}, {...valid, key: `${boundaryKey}x`}), HostedAnswerError);
  for (const contentType of ["image/svg+xml\r\nx-extra: value", "image/非ascii", " image/svg+xml", "image/svg+xml ", "x".repeat(1025)])
    assert.throws(() => parseBlobWriteResult({...json(create), data: {...json(create).data, contentType}}, {...valid, contentType} as BlobWriteExpected), HostedAnswerError);
});

test("blob conflicts retain exact preconditions and coherent nullable current-head metadata", () => {
  for (const name of ["blob-create-200-conflict", "blob-replace-200-stale-type", "blob-delete-200-absent"]) {
    const exchange = fixture(name), expected = expectedFor(exchange), good = json(exchange);
    assert.deepEqual(parseBlobWriteResult(good, expected), good);
    for (const error of [
      {...good.error, expected: digest("a")}, {...good.error, expectedContentType: "application/pdf"},
      {...good.error, actual: null, actualContentType: "application/pdf"},
      {...good.error, actual: digest("a"), actualContentType: null},
      {...good.error, writeState: "unknown"}, {...good.error, code: "new_error"},
    ]) assert.throws(() => parseBlobWriteResult({...good, error}, expected), HostedAnswerError, name);
  }
  const stale = fixture("blob-replace-200-stale-type"), expected = expectedFor(stale), good = json(stale);
  assert.throws(() => parseBlobWriteResult({...good, error: {...good.error, actual: expected.expectedVersion, actualContentType: expected.expectedContentType}}, expected), HostedAnswerError);
});

test("blob outcome identity and terminal status cannot substitute later heads or document content", () => {
  for (const name of ["blob-outcome-200-original", "blob-outcome-200-refused", "blob-outcome-200-absent"]) {
    const exchange = fixture(name), expected = {...expectedFor(exchange), ...identityFor(exchange)}, good = json(exchange);
    assert.equal(decodeBlobOutcomeAnswer(good, expected).status, good.status);
    for (const value of [
      {...good, requestId: "11111111-1111-4111-8111-111111111111"},
      {...good, binding: digest("a")}, {...good, schemaVersion: 2},
      {...good, status: "pending"}, {...good, content: {encoding: "base64", bytes: ""}},
      {...good, status: good.status === "committed" ? "refused" : "committed"},
    ]) assert.throws(() => decodeBlobOutcomeAnswer(value, expected), HostedOutcomeError, name);
    if (good.status !== "absent") {
      const swapped = clone(good);
      swapped.result.operationId = "documents.delete.v1";
      assert.throws(() => decodeBlobOutcomeAnswer(swapped, expected), HostedOutcomeError);
      if (good.status === "committed") assert.throws(() => decodeBlobOutcomeAnswer(good, {...expected, key: "another.svg"}), HostedOutcomeError);
    }
  }
  const committed = fixture("blob-outcome-200-original"), original = json(committed);
  const success = decodeBlobOutcomeAnswer(original, {...expectedFor(committed), ...identityFor(committed)});
  assert.equal(success.status, "committed");
  if (success.status === "committed") assert.equal(success.result.data.contentType, "image/svg+xml; charset=utf-8");
  // The fixture's original result predates the subsequent type-only replacement.
  assert.notEqual(original.result.data.contentType, json(fixture("blob-replace-200-type-only")).data.contentType);
});

test("blob writes reuse common quota, hold and authority carrier rows without a document operation", () => {
  const create = expectedFor(fixture("blob-create-200-ok"));
  const deletion = expectedFor(fixture("blob-delete-200-ok"));
  const answer = (status: number, error: unknown): HostedAnswer => ({status, headers: new Headers(), body: {error}});
  const cases = [
    [401, {writeState: "not_applied"}, "401 not_applied"],
    [401, {code: "write_outcome_unknown"}, "401 write_outcome_unknown"],
    [403, {code: "access_denied"}, "403"], [503, {code: "write_outcome_unknown"}, "503"],
    [400, {code: "invalid_input"}, "400"],
  ] as const;
  for (const [status, error, row] of cases) assert.equal(classifyBlobWriteAnswer(answer(status, error), create).row.answer, row);
  const quota = classifyBlobWriteAnswer(answer(429, {code: "request_capacity", scope: "principal"}), create);
  assert.equal(quota.row.answer, "429 request_capacity");
  assert.equal(quota.result?.operationId, "blobs.create.v1");
  const held = answer(428, {code: "deletions_held", message: "Confirm", retryable: false, writeState: "not_applied", deletions: 3, baseline: 4});
  assert.equal(classifyBlobWriteAnswer(held, deletion).row.answer, "428 deletions_held");
  assert.equal(classifyBlobWriteAnswer(held, create).row.answer, "other status");
  assert.equal(classifyBlobWriteAnswer({status: 200, headers: new Headers(), body: {ok: true}}, create).row.outcome, "unknown");
});

test("blob capabilities fail closed on older flags and malformed independent byte bounds", () => {
  const current = JSON.parse(readFileSync(path.join(directory, "capabilities-200.json"), "utf8")).response.body;
  const body = JSON.parse(current);
  const decoded = decodeHostedCapabilities(body);
  assert.equal(decoded.blobReads, "allowed"); assert.equal(decoded.blobWrites, "allowed");
  assert.equal(decoded.blobReadBytes, body.limits.blobReadBytes); assert.equal(decoded.blobWriteBytes, body.limits.blobWriteBytes);
  const {blobReads: _reads, blobWrites: _writes, ...older} = body;
  assert.equal(decodeHostedCapabilities(older).blobReads, "refused"); assert.equal(decodeHostedCapabilities(older).blobWrites, "refused");
  const noLimits = decodeHostedCapabilities({...body, limits: undefined});
  assert.equal(noLimits.blobReads, "refused"); assert.equal(noLimits.blobWrites, "refused");
  assert.equal(noLimits.blobReadBytes, null); assert.equal(noLimits.blobWriteBytes, null);
  const readOnly = decodeHostedCapabilities({...body, blobWrites: "refused"});
  assert.equal(readOnly.blobReads, "allowed"); assert.equal(readOnly.blobWrites, "refused");
  for (const value of [undefined, null, 0, -1, 1.5, Number.NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, "16777216"]) {
    const read = decodeHostedCapabilities({...body, limits: {...body.limits, blobReadBytes: value}});
    assert.equal(read.blobReadBytes, null); assert.equal(read.blobReads, "refused"); assert.equal(read.blobWrites, "allowed");
    const write = decodeHostedCapabilities({...body, limits: {...body.limits, blobWriteBytes: value}});
    assert.equal(write.blobWriteBytes, null); assert.equal(write.blobWrites, "refused"); assert.equal(write.blobReads, "allowed");
  }
  for (const value of [undefined, true, "yes", {}, 1]) {
    const decoded = decodeHostedCapabilities({...body, blobReads: value, blobWrites: value});
    assert.equal(decoded.blobReads, "refused"); assert.equal(decoded.blobWrites, "refused");
  }
});
